const baseFare = $fromAI('base_fare', 'Base ticket price', 'number', 200);
const cabinClass = $fromAI('cabin_class', 'Cabin class: economy, premium, business, or first', 'string', 'economy');
const checkedBags = $fromAI('checked_bags', 'Number of checked bags', 'number', 0);

// Cabin multipliers
const multipliers = {
  economy: 1.0,
  premium: 1.5,
  business: 2.5,
  first: 4.0
};

const multiplier = multipliers[cabinClass.toLowerCase()] || 1.0;
const adjustedFare = baseFare * multiplier;

// Taxes and fees (15% of fare)
const taxes = adjustedFare * 0.15;

// Baggage fees ($35 per bag)
const baggageFees = checkedBags * 35;

// Total
const total = adjustedFare + taxes + baggageFees;

return {
  baseFare: baseFare.toFixed(2),
  cabinClass: cabinClass,
  adjustedFare: adjustedFare.toFixed(2),
  taxes: taxes.toFixed(2),
  baggageFees: baggageFees.toFixed(2),
  checkedBags: checkedBags,
  totalFare: total.toFixed(2),
  currency: 'USD'
};
